// ──────────────────────────────────────────────
// Hot Wheels mainline catalogue (generated by scripts/import-hw-catalog.mjs
// from the Hot Wheels Wiki, CC BY-SA). Loaded lazily, once, on first use.
// ──────────────────────────────────────────────

import type { CatalogEntry } from './matcher.ts';

interface CatalogFile {
  version: number;
  generatedAt: string;
  years: [number, number];
  source: string;
  license: string;
  imageBase: string;
  fields: string[];
  rows: [string, string, string, string, string, string, number, 0 | 1, string][];
}

export interface HotWheelsCatalog {
  entries: CatalogEntry[];
  years: [number, number];
  generatedAt: string;
  license: string;
}

const CATALOG_URL = '/catalog/hotwheels.json';
let cache: Promise<HotWheelsCatalog> | null = null;

function imageUrl(base: string, compact: string): string | null {
  if (!compact) return null;
  if (compact.startsWith('https://')) return compact;
  const [p, cb] = compact.split('|');
  // v=2 busts any hotlink placeholder a browser cached before we sent no-referrer.
  return `${base}${p}/revision/latest/scale-to-width-down/480?${cb ? `cb=${cb}&` : ''}v=2`;
}

/** The wiki filename is our best caption: it often says "loose", "carded", etc. */
function captionFromPath(compact: string): string {
  const file = compact.split('|')[0]?.split('/').pop() ?? '';
  try {
    return decodeURIComponent(file).replace(/\.[a-z]+$/i, '').replace(/_/g, ' ');
  } catch {
    return file;
  }
}

export function parseCatalog(file: CatalogFile): HotWheelsCatalog {
  const entries = file.rows.map(([toy, col, name, variant, series, seriesNum, year, , img]): CatalogEntry => ({
    key: `hw:${year}:${toy}`,
    source: 'catalog',
    name,
    variant,
    brand: 'Hot Wheels',
    series,
    seriesNumber: seriesNum,
    releaseYear: year,
    modelNumber: toy,
    collectorNumber: col,
    imageUrl: imageUrl(file.imageBase, img),
    imageCaption: captionFromPath(img),
    sourceUrl: `https://hotwheels.fandom.com/wiki/List_of_${year}_Hot_Wheels`,
  }));
  return { entries, years: file.years, generatedAt: file.generatedAt, license: file.license };
}

export function loadHotWheelsCatalog(): Promise<HotWheelsCatalog> {
  if (!cache) {
    cache = fetch(CATALOG_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`Catalogue HTTP ${res.status}`);
        return res.json() as Promise<CatalogFile>;
      })
      .then(parseCatalog);
    cache.catch(() => {
      cache = null; // allow a retry later
    });
  }
  return cache;
}
